sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    helpers.showLoadingIndicator();
api.data.record_3.save().then(() => {
    helpers.hideLoadingIndicator();
    api.navigator.navigate({ page: "record_details_page", parameters: { sys_id: api.data.record_3.sys_id } });
}).catch((error) => {
    helpers.hideLoadingIndicator();
    console.error("Error saving record:", error);
    helpers.showNotification("Failed to save the record. Please try again.", "error");
});
}
